// Bundles the overworld biome parameter list and per-biome climate settings into one compact text
// file: crates/rine-worldgen/assets/worldgen/overworld_biomes.txt.
// Source: vanilla-data/generated/reports/biome_parameters/minecraft/overworld.json (datagen report,
// list order preserved, since the RTree tie-break depends on it) and worldgen/biome/*.json.
// Usage: node tools/noise-golden/bundle_worldgen.js
const fs = require('fs');
const path = require('path');

const REPO = path.resolve(__dirname, '..', '..');
const VANILLA = path.join(REPO, 'vanilla-data', 'generated');
const REPORT = path.join(VANILLA, 'reports', 'biome_parameters', 'minecraft', 'overworld.json');
const BIOME_DIR = path.join(VANILLA, 'data', 'minecraft', 'worldgen', 'biome');
const OUT = path.join(REPO, 'crates', 'rine-worldgen', 'assets', 'worldgen', 'overworld_biomes.txt');

const report = JSON.parse(fs.readFileSync(REPORT, 'utf8'));
const names = [];
const index = new Map();
for (const entry of report.biomes) {
    if (!index.has(entry.biome)) {
        index.set(entry.biome, names.length);
        names.push(entry.biome);
    }
}

const lines = [];
lines.push('# @generated by tools/noise-golden/bundle_worldgen.js. Do not edit.');
lines.push('# Overworld multi-noise biome parameter list (datagen report order) and biome climate settings.');
lines.push('# B <biome> <temperature> <temperature_modifier>   (one per distinct biome, index = line order)');
lines.push('# P <biome index> <temperature> <humidity> <continentalness> <erosion> <depth> <weirdness> <offset>');
lines.push('# Each parameter is "min max" (floats, as printed by the report). Quantization happens in Rust.');
for (const name of names) {
    const file = path.join(BIOME_DIR, name.replace('minecraft:', '') + '.json');
    const biome = JSON.parse(fs.readFileSync(file, 'utf8'));
    const modifier = biome.temperature_modifier || 'none';
    lines.push(`B ${name} ${JSON.stringify(biome.temperature)} ${modifier}`);
}
for (const entry of report.biomes) {
    const p = entry.parameters;
    const span = (v) => (Array.isArray(v) ? `${JSON.stringify(v[0])} ${JSON.stringify(v[1])}` : `${JSON.stringify(v)} ${JSON.stringify(v)}`);
    lines.push(
        `P ${index.get(entry.biome)} ${span(p.temperature)} ${span(p.humidity)} ${span(p.continentalness)} ${span(p.erosion)} ${span(p.depth)} ${span(p.weirdness)} ${JSON.stringify(p.offset)}`
    );
}

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, lines.join('\n') + '\n');
console.log(`bundled ${report.biomes.length} parameter points, ${names.length} biomes -> ${OUT}`);

// Default block states (canonical "name[k=v,...]", property order as in reports/blocks.json) for every
// plain block id the overworld material rules and aquifer can emit.
{
    const DATA = path.join(VANILLA, 'data', 'minecraft', 'worldgen');
    const blocksReport = JSON.parse(fs.readFileSync(path.join(VANILLA, 'reports', 'blocks.json'), 'utf8'));
    const found = new Set(['minecraft:air', 'minecraft:stone', 'minecraft:water', 'minecraft:lava', 'minecraft:bedrock', 'minecraft:light_gray_terracotta', 'minecraft:yellow_terracotta', 'minecraft:brown_terracotta', 'minecraft:red_terracotta']);
    const walk = (dir) => {
        for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
            const p = path.join(dir, e.name);
            if (e.isDirectory()) walk(p);
            else if (p.endsWith('.json')) {
                for (const m of fs.readFileSync(p, 'utf8').matchAll(/"(minecraft:[a-z_]+)"/g)) found.add(m[1]);
            }
        }
    };
    walk(path.join(DATA, 'material_rule'));
    walk(path.join(DATA, 'material_condition'));
    const out = ['# @generated by tools/noise-golden/bundle_worldgen.js. Do not edit.',
        '# Default state of every plain block id used by the overworld rules: <block id> <canonical state>.'];
    for (const name of [...found].sort()) {
        const block = blocksReport[name];
        if (!block) continue;
        const state = block.states.find((s) => s.default);
        const props = Object.keys(block.properties || {});
        const body = props.map((k) => `${k}=${state.properties[k]}`).join(',');
        out.push(`${name} ${name}${props.length ? '[' + body + ']' : ''}`);
    }
    const dst = path.join(REPO, 'crates', 'rine-worldgen', 'assets', 'worldgen', 'block_states.txt');
    fs.writeFileSync(dst, out.join('\n') + '\n');
    console.log(`block states: ${out.length - 2} -> ${dst}`);
}
